Assume that $\mathcal{A}=\{A_k\}$ satisfies generalized hyperbolicity
with constants $C>0$, $\lambda\in(0,1)$ and $\|A_k\|,\|A_k^{-1}\|\leq R$, for $k\in\mathbb{Z}$. 
Then for any $\lambda_1 \in (\lambda, 1)$, there exist $C_1 = C_1(C, \lambda, \lambda_1, R)$ and $\varepsilon > 0$ such that 
    \begin{itemize}
        \item[(Robust1)]  any sequence $\mathcal{B} = \{B_k\}_{k \in \mathbb{Z}}$, where 
\begin{equation}
        \|B_k - A_k\| < \varepsilon, \quad k \in \mathbb{Z}  
\end{equation}
        also satisfies generalized hyperbolicity with constants $C_1$, $\lambda_1$;
        \item [(Robust2)] if, in addition, the sequence $\mathcal{A}$ is $m$-periodic and satisfies periodic generalized hyperbolicity, then any $m$-periodic sequence $\mathcal{B} = \{B_k\}_{k \in \mathbb{Z}}$ satisfying (33) also satisfies periodic generalized hyperbolicity with constants $C_1$, $\lambda_1$.
    \end{itemize}

Assume that $(\alpha, A)$ satisfies the uniformly continuous cocycle generalized hyperbolicity with constants~$C, \lambda$. Then there exists $L = L(\lambda, C)$, such that the restriction $T_{\alpha, A}: Y \to X$ is a bijection and admits a bounded inverse  
\begin{equation}
S_{\alpha, A} = T^{-1}_{\alpha, A}: X \to Y, \quad \|S_{\alpha, A}\| \leq L.
\end{equation}

Assume that the pair $(\alpha, A)$ satisfies uniformly continuous cocycle generalized hyperbolicity with constants $C > 0$, $\lambda \in (0, 1)$. Then for any $\lambda_1 \in (\lambda, 1)$ and $\varepsilon >0$ there exist $C_1 > 1$ and $\delta >0$ such that for any homeomorphism $\beta: \mathbb{B} \to \mathbb{B}$, with $\beta$ and $\beta^{-1}$ uniformly continuous, satisfying 
\begin{equation}
    |\alpha(x) - \beta(x)|, |\alpha^{-1}(x) - \beta^{-1}(x)| < \delta, \quad x \in \mathbb{B}    
\end{equation}
 there exist mappings $H^s_x: E_x^s \to F_x \subset E_x^u$, $H^u_{x}: E_{\alpha(x)}^u \to A(x)E_x^s \subset E_{\alpha(x)}^s$ that depend uniformly continuously on $x$ such that
    $
    \|H^s_x\|, \|H^u_x\| < \varepsilon
    $
    and the pair $(\beta, A)$ satisfies uniformly continuous cocycle generalized hyperbolicity with constants $(C_1, \lambda_1)$ and spaces 
\begin{align*}
    \tilde{E}_x^s &= (Id + H^s_x)E^s_x = \{v+H^s_x v: v \in E^s_x\},\\
        \tilde{E}_{\beta(x)}^u &= (Id + H^u_x)E^u_{\alpha(x)} = \{v+H^u_x v: v \in E^u_{\alpha(x)}\}.    
\end{align*}
There exists $\varepsilon_0$ such that if $\varepsilon < \varepsilon_0$ then 
\begin{equation}
    \tilde{E}^s_x \oplus A^{-1}(x)\tilde{E}^u_{\beta(x)} = E^s_x \oplus F_x.
\end{equation}

If $f \in \mathfrak{D}(\mathbb{B})$ satisfies uniformly continuous generalized hyperbolicity, then there exist $M>0$, $d_0 > 0$ such that for any $d \in (0, d_0)$ and diffeomorphism $g \in \mathfrak{D}(\mathbb{B})$ with $\|f-g\|_{C^1} < d$ the following holds.
    \begin{enumerate}[
    label=\textup{(S\arabic*)},
    ref=\textup{S\arabic*}
]
        \item 
            There exist uniformly continuous maps $h_1, h_2:\mathbb{B} \to \mathbb{B}$ satisfying
        \begin{equation}
        g \circ (Id+h_1) = (Id + h_1) \circ f,
        \end{equation}
        \begin{equation}
        f \circ (Id+h_2) = (Id + h_2) \circ g,
        \end{equation}
        \begin{equation}
        |h_1(x)|, |h_2(x)| < Md, \quad x \in \mathbb{B},
        \end{equation}
        hence $f$ is uniformly semi-structurally stable.
        \item 
        If additionally the spaces $E^s_x \oplus (Df(x))^{-1}E^u_{f(x)}$ do not depend on $x$, then $h_1$, $h_2$ can be chosen such that 
        \begin{equation}
        (Id+h_1) \circ (Id+h_2) = Id, \quad (Id+h_2) \circ (Id+h_1) = Id.
        \end{equation}
In that case, the maps $(Id+h_1)$, $(Id+h_2)$ are homeomorphisms, and hence $f$ is uniformly structurally stable.
    \end{enumerate}
